using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace OpenAntiLag {
 public sealed class TrafficPage:ToolPage {
  readonly ComboBox process,mode;readonly TextBox path,exceptions;readonly NumericUpDown limit,dscp;readonly CheckBox mark;readonly NetworkClient client;
  public TrafficPage(bool preview,Func<bool> acquire,Action release,NetworkClient client=null):base("Трафик",preview,acquire,release){this.client=client??new NetworkClient();Name="trafficPage";Note("QoS Windows ограничивает только исходящий трафик. DSCP может игнорироваться сетью. Число соединений — не скорость и не доказанная нагрузка. Windows/античит/защитные процессы исключены.");mode=Choice(260);mode.Items.AddRange(new object[]{"Без ограничений — восстановление","Игровой — 2 Мбит/с фоновому EXE","Пользовательский"});mode.SelectedIndex=2;process=Choice(310);path=Field("",550);limit=Number(0,1000000,2);limit.DecimalPlaces=2;mark=new CheckBox {Text="Назначить DSCP",AutoSize=true};dscp=Number(0,63,0);exceptions=Field("faceitclient,faceitservice,cs2",500);Row(mode);Row(Caption("Выбранный процесс"),process);Row(ActionButton("Обновить процессы",async ct=>{var list=await Task.Run(()=>GameConnections.Processes(),ct);process.Items.Clear();foreach(var p in list.Where(p=>!GameConnections.IsProtected(p.Path)))process.Items.Add(p);if(process.Items.Count>0)process.SelectedIndex=0;var connections=await Task.Run(()=>GameConnections.Read(),ct);ShowText(String.Join("\r\n",list.Where(p=>connections.Any(c=>c.ProcessId==p.Id)).Select(p=>p+" · endpoints="+connections.Count(c=>c.ProcessId==p.Id)))+"\r\nБайт/с по процессу недоступны. Для общей скорости смотрите адаптеры/историю.");}),ActionButton("Проверить QoS Windows",async ct=>{string result=await Task.Run(()=>WindowsNetworkHost.Capability("QoS"),ct);if(!result.StartsWith("Доступно",StringComparison.Ordinal))RestrictNamed("Применить QoS (UAC)");ShowText(result);}));
   process.SelectedIndexChanged+=delegate{var p=process.SelectedItem as GameProcess;if(p!=null)path.Text=p.Path;};Row(Caption("Полный путь EXE"),path);Row(Caption("Лимит исходящего, Мбит/с (0 — без лимита)"),limit);Row(mark,dscp);Row(Caption("Исключения, имена без .exe через запятую"),exceptions);Row(ActionButton("Исключения из профиля",ct=>{var selected=GameProfileManager.Load(Path.Combine(Program.DataDirectory,"network-profile.json"));exceptions.Text=String.Join(",",selected.Exclusions);return Task.FromResult(0);}));
   Row(ActionButton("Применить QoS (UAC)",async ct=>{if(mode.SelectedIndex==0){await Task.Run(()=>this.client.Run("restore-qos",new NetworkRequest()));return;}if(mode.SelectedIndex==1){limit.Value=2;mark.Checked=false;}string executable=Path.GetFullPath(path.Text.Trim());if(GameConnections.IsProtected(executable)||!File.Exists(executable))throw new ArgumentException("Нужен существующий пользовательский EXE; системные/защитные процессы запрещены");if(exceptions.Text.Split(',').Select(x=>x.Trim()).Contains(Path.GetFileNameWithoutExtension(executable),StringComparer.OrdinalIgnoreCase))throw new InvalidOperationException("Приложение в исключениях. Удалите исключение только если намерены настраивать этот EXE.");var policy=new QosPolicy {Name="OpenAntiLag-"+Guid.NewGuid().ToString("N"),Path=executable,BitsPerSecond=(long)(limit.Value*1000000),Dscp=mark.Checked?(int)dscp.Value:-1};NetworkValidation.Qos(policy);if(MessageBox.Show(this,"Создать временную политику QoS для:\n"+executable+"\nЛимит: "+limit.Value+" Мбит/с; DSCP: "+policy.Dscp+"?\nЭто затронет все экземпляры этого EXE. Политика ActiveStore исчезнет после перезагрузки.","Применить QoS",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)throw new OperationCanceledException("Действие отменено пользователем");await Task.Run(()=>this.client.Run("qos",new NetworkRequest {Qos=policy}));Log("Политика создана и прочитана обратно. Эффективность ограничения на этой Windows не гарантируется политиками/драйвером.");},true),ActionButton("Восстановить QoS (UAC)",async ct=>{await Task.Run(()=>this.client.Run("restore-qos",new NetworkRequest()));Log("Созданные приложением политики восстановлены; отличающиеся внешние политики не удаляются.");},true));
   Row(ActionButton("Журнал / восстановление",ct=>{var state=this.client.State;ShowText("Сохранено QoS: "+state.Qos.Count+"; DNS: "+state.Dns.Count+".\r\n"+String.Join("\r\n",state.Qos.Select(q=>q.Applied.Name+" · "+q.Applied.Path)));return Task.FromResult(0);}));Note("При обычном выходе из трея приложение предложит отдельный UAC для удаления своих QoS. После сбоя используйте «Восстановить QoS». Отмена UAC сохраняет журнал для повтора.");
  }
 }
 public sealed class DnsPage:ToolPage {
  readonly ComboBox adapters,family,provider,apiProfiles;readonly TextBox servers,domain,key,profile,entry;readonly NumericUpDown repeats;readonly CheckBox privateData;readonly NetworkClient client;readonly ApiKeyStore keys=new ApiKeyStore();
  public DnsPage(bool preview,Func<bool> acquire,Action release,NetworkClient client=null):base("DNS",preview,acquire,release){this.client=client??new NetworkClient();Name="dnsPage";Note("Назначение DNS-серверов не включает DoH/DoT. Шифрование DNS средствами этой версии не настраивается. Подключение API NextDNS не переключает DNS Windows. Запросы сравнения идут напрямую выбранному серверу UDP/53; кэш самого сервера влияет на результат.");adapters=Choice(380);family=Choice(90);family.Items.AddRange(new object[]{"IPv4","IPv6"});family.SelectedIndex=0;provider=Choice(220);provider.Items.AddRange(new object[]{"Пользовательский","Cloudflare","Google","Quad9"});provider.SelectedIndex=0;servers=Field("1.1.1.1, 1.0.0.1",450);domain=Field("example.com",250);repeats=Number(2,10,3);Row(adapters,family);Row(provider,servers);family.SelectedIndexChanged+=delegate{SetProvider();};provider.SelectedIndexChanged+=delegate{SetProvider();};Row(Caption("Домен для DNS-теста"),domain,Caption("Повторов"),repeats);
   Row(ActionButton("Адаптеры и текущий DNS",async ct=>{var all=await Task.Run(()=>NetworkAdapters.Read(),ct);adapters.Items.Clear();foreach(var a in all.Where(x=>x.Type!="Loopback"))adapters.Items.Add(a);if(adapters.Items.Count>0)adapters.SelectedIndex=0;ShowText(String.Join("\r\n\r\n",all.Select(NetworkAdapters.Describe)));}),ActionButton("Сравнить DNS",async ct=>{string host=NetworkInput.Host(domain.Text);int version=family.SelectedIndex==0?4:6;string[] selected=NetworkInput.Servers(servers.Text,version);var adapter=adapters.SelectedItem as AdapterSnapshot;var list=selected.Concat(adapter==null?new string[0]:adapter.Dns).Distinct().Take(8).ToArray();int count=(int)repeats.Value;foreach(string server in list){var results=new System.Collections.Generic.List<DnsMeasurement>();for(int i=0;i<count;i++){ct.ThrowIfCancellationRequested();results.Add(await DnsProbe.Query(server,host,ct));await Task.Delay(250,ct);}var success=results.Where(r=>r.Success).ToArray();Log(server+": ответов "+success.Length+"/"+count+(success.Length>0?"; медиана "+ProbeSummary.Percentile(success.Select(r=>r.Milliseconds).OrderBy(x=>x).ToArray(),.5).ToString("0.0")+" мс":"; "+results.Last().Error));}Log("Это сравнение DNS-резолвинга, а не ping игрового сервера. Никакой flushdns не выполнялся.");}));
   Row(ActionButton("Назначить DNS (UAC)",async ct=>{var a=adapters.SelectedItem as AdapterSnapshot;if(a==null)throw new ArgumentException("Выберите адаптер");int version=family.SelectedIndex==0?4:6;var requested=new DnsConfig {Adapter=a.Id,Family=version,Servers=NetworkInput.Servers(servers.Text,version)};if(MessageBox.Show(this,"Назначить обычный DNS IPv"+version+" адаптеру "+a.Name+"?\n"+String.Join(", ",requested.Servers)+"\nИсходный DHCP/static режим будет сохранён. Возможен кратковременный разрыв DNS.","DNS Windows",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)throw new OperationCanceledException("Действие отменено пользователем");await Task.Run(()=>this.client.Run("dns",new NetworkRequest {Dns=requested}));Log("DNS записан и проверен. Это не DoH/DoT.");},true),ActionButton("Восстановить DNS (UAC)",async ct=>{await Task.Run(()=>this.client.Run("restore-dns",new NetworkRequest()));Log("Сохранённые конфигурации DNS восстановлены. При внешних изменениях журнал остаётся для проверки.");},true),ActionButton("Доступность DNS-модуля",async ct=>{string result=await Task.Run(()=>WindowsNetworkHost.Capability("DNS"),ct);if(!result.StartsWith("Доступно",StringComparison.Ordinal))RestrictNamed("Назначить DNS (UAC)");ShowText(result);}));
   Note("NextDNS API — необязательно. Ключ хранится DPAPI только для текущего пользователя. Для управления списками нужен ID вашей конфигурации. Данные аккаунта загружаются только по кнопке.");key=Field("",330);key.UseSystemPasswordChar=true;profile=Field("",110);apiProfiles=Choice(260);Row(Caption("API key"),key,ActionButton("Сохранить ключ DPAPI",ct=>{keys.Save(key.Text);key.Clear();Log("Ключ защищён DPAPI; полностью в UI/логе не выводится.");return Task.FromResult(0);}));Row(ActionButton("Удалить сохранённый ключ",ct=>{keys.Delete();key.Clear();return Task.FromResult(0);}),Caption("ID профиля"),profile);
   Row(ActionButton("Список конфигураций",async ct=>{using(var api=new NextDnsClient(keys.Load())){string response=await api.Profiles(ct);ShowText(response);var data=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(response);apiProfiles.Items.Clear();object raw;if(data.TryGetValue("data",out raw)&&raw is object[])foreach(var item in (object[])raw){var row=item as System.Collections.Generic.Dictionary<string,object>;if(row!=null&&row.ContainsKey("id"))apiProfiles.Items.Add(Convert.ToString(row["id"]));}if(apiProfiles.Items.Count>0)apiProfiles.SelectedIndex=0;}}),apiProfiles);apiProfiles.SelectedIndexChanged+=delegate{if(apiProfiles.SelectedItem!=null)profile.Text=apiProfiles.SelectedItem.ToString();};Note("Если список конфигураций не поддерживается API аккаунта, введите ID вручную. Управление профилем использует документированные /profiles/:id endpoints.");
   entry=Field("example.com",270);privateData=new CheckBox {Text="Разрешаю получить личную статистику/логи NextDNS",AutoSize=true};Row(Caption("Домен списка"),entry);
   foreach(string name in new[]{"allowlist","denylist"}){string list=name;Row(ActionButton("Прочитать "+list,async ct=>{using(var api=new NextDnsClient(keys.Load()))ShowText(await api.List(profile.Text,list,ct));}),ActionButton("Добавить в "+list,ct=>Change(list,false,ct)),ActionButton("Удалить из "+list,ct=>Change(list,true,ct)));}
   Row(privateData);Row(ActionButton("Статистика NextDNS",ct=>Private(false,ct)),ActionButton("Логи NextDNS (до 100)",ct=>Private(true,ct)),ActionButton("Проверить путь NextDNS",async ct=>{using(var http=new System.Net.Http.HttpClient(new System.Net.Http.HttpClientHandler {AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(10),MaxResponseContentBufferSize=65536}){var response=await http.GetAsync("https://test.nextdns.io",ct);response.EnsureSuccessStatusCode();ShowText(await response.Content.ReadAsStringAsync()+"\r\nЭто путь DNS только данного тестового запроса. Браузеры/приложения с собственным DoH могут использовать другой DNS. Сравните возвращённый profile с вашим ID; назначение IP-серверов само по себе не подтверждает выбор профиля.");}}));
  }
  void SetProvider(){if(provider.SelectedIndex==0)return;bool v6=family.SelectedIndex==1;servers.Text=provider.SelectedIndex==1?(v6?"2606:4700:4700::1111,2606:4700:4700::1001":"1.1.1.1,1.0.0.1"):provider.SelectedIndex==2?(v6?"2001:4860:4860::8888,2001:4860:4860::8844":"8.8.8.8,8.8.4.4"):(v6?"2620:fe::fe,2620:fe::9":"9.9.9.9,149.112.112.112");}
  async Task Change(string list,bool remove,CancellationToken ct){string host=NextDnsClient.Domain(entry.Text),id=NextDnsClient.Profile(profile.Text);if(MessageBox.Show(this,(remove?"Удалить ":"Добавить ")+host+" · "+list+" · профиль "+id+"?","NextDNS",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)throw new OperationCanceledException("Действие отменено пользователем");using(var api=new NextDnsClient(keys.Load())){try{await api.Change(id,list,host,remove,ct);ShowText(await api.List(id,list,ct));}catch(OperationCanceledException){Log("API-запрос отменён. Проверьте список: сервер мог успеть сохранить изменение.");throw;}}}
  async Task Private(bool logs,CancellationToken ct){if(!privateData.Checked)throw new InvalidOperationException("Сначала разрешите чтение личных данных аккаунта");using(var api=new NextDnsClient(keys.Load()))ShowText(await api.PrivateData(profile.Text,logs,ct));}
 }
}
